/** Every icon key (kebab-case, shared with every package: the npm packages' `names`), in key order. */
val PulsoIcons.ICON_NAMES: List<String> get() = names

/** Every icon by key. Builds all of them; prefer [byKey] for a single lookup. */
val PulsoIcons.ICONS: Map<String, PulsoIconSpec> get() = names.associateWith { byKey(it)!! }

/** First key of each lookup chunk. */
private val chunkStarts = arrayOf("a-arrow-down", "assembly-off", "brackets-contain", "brand-burp-suite", "brand-electron-builder", "brand-hitachi", "brand-mariadb-foundation", "brand-phosphor-icons", "brand-sidequest", "brand-unity", "calendar-question", "circle-dotted-letter-y", "crop-16-9", "drone-off", "files-off", "grave-2", "infinity-2", "location-star", "metro", "olympic-torch", "precision-tool", "search-off", "split", "table-heart", "user-bag")

/** The icon stored under [key] (e.g. a venue amenity), or null for an unknown key. */
fun PulsoIcons.byKey(key: String): PulsoIconSpec? {
    val found = chunkStarts.binarySearch(key)
    return when (if (found >= 0) found else -found - 2) {
        0 -> chunk0(key)
        1 -> chunk1(key)
        2 -> chunk2(key)
        3 -> chunk3(key)
        4 -> chunk4(key)
        5 -> chunk5(key)
        6 -> chunk6(key)
        7 -> chunk7(key)
        8 -> chunk8(key)
        9 -> chunk9(key)
        10 -> chunk10(key)
        11 -> chunk11(key)
        12 -> chunk12(key)
        13 -> chunk13(key)
        14 -> chunk14(key)
        15 -> chunk15(key)
        16 -> chunk16(key)
        17 -> chunk17(key)
        18 -> chunk18(key)
        19 -> chunk19(key)
        20 -> chunk20(key)
        21 -> chunk21(key)
        22 -> chunk22(key)
        23 -> chunk23(key)
        24 -> chunk24(key)
        else -> null
    }
}
